with player_games as (
    select * from {{ ref('player_game') }}
),

box_scores as (
    select * from {{ ref('stg_box_scores') }}
),

advanced_box_scores as (
    select * from {{ ref('stg_advanced_box_scores') }}
),

player_tracking as (
    select * from {{ ref('stg_player_tracking_box_scores') }}
),

box_score_usage as (
    select * from {{ ref('stg_box_score_usage') }}
),

player_stats as (
    select
        pg.game_id,
        pg.player_id,
        pg.game_date,
        pg.season,
        pg.opponent_team_id,
        -- box scores
        bs.team_id,
        bs.player_name,
        bs.player_position,
        bs.start_position,
        bs.field_goals_made,
        bs.field_goals_attempted,
        bs.three_pointers_made,
        bs.three_pointers_attempted,
        bs.free_throws_made,
        bs.free_throws_attempted,
        bs.points,
        bs.offensive_rebounds,
        bs.defensive_rebounds,
        (bs.offensive_rebounds + bs.defensive_rebounds) as rebounds,
        bs.assists,
        bs.steals,
        bs.blocks,
        bs.turnovers,
        bs.personal_fouls,
        bs.minutes_played,
        bs.plus_minus,
        bs.comments,
        -- advanced box scores (excluding duplicates)
        ab.off_rating,
        ab.def_rating,
        ab.net_rating,
        ab.e_off_rating,
        ab.e_def_rating,
        ab.e_net_rating,
        ab.ast_pct,
        ab.ast_to,
        ab.ast_ratio,
        ab.oreb_pct,
        ab.dreb_pct,
        ab.reb_pct,
        ab.tm_tov_pct,
        ab.efg_pct,
        ab.ts_pct,
        ab.usg_pct,
        ab.e_usg_pct,
        ab.e_pace,
        ab.pace,
        ab.pace_per40,
        ab.poss,
        ab.pie,
        -- player tracking (excluding duplicates)
        pt.speed,
        pt.distance,
        pt.offensive_rebounds_contested,
        pt.defensive_rebounds_contested,
        pt.rebounds_contested,
        pt.touches,
        pt.secondary_assists,
        pt.free_throw_assists,
        pt.passes,
        pt.contested_field_goals_made,
        pt.contested_field_goals_attempted,
        pt.contested_field_goal_pct,
        pt.uncontested_field_goals_made,
        pt.uncontested_field_goals_attempted,
        pt.uncontested_field_goal_pct,
        pt.field_goal_pct as tracking_field_goal_pct,
        pt.defended_field_goals_made,
        pt.defended_field_goals_attempted,
        pt.defended_field_goal_pct,
        -- box score usage (excluding duplicates)
        bu.pct_fgm,
        bu.pct_fga,
        bu.pct_fg3m,
        bu.pct_fg3a,
        bu.pct_ftm,
        bu.pct_fta,
        bu.pct_oreb,
        bu.pct_dreb,
        bu.pct_reb,
        bu.pct_ast,
        bu.pct_tov,
        bu.pct_stl,
        bu.pct_blk,
        bu.pct_blka,
        bu.pct_pf,
        bu.pct_pfd,
        bu.pct_pts
    from player_games pg
    left join box_scores bs on pg.game_id = bs.game_id and pg.player_id = bs.player_id
    left join advanced_box_scores ab on pg.game_id = ab.game_id and pg.player_id = ab.player_id
    left join player_tracking pt on pg.game_id = pt.game_id and pg.player_id = pt.player_id
    left join box_score_usage bu on pg.game_id = bu.game_id and pg.player_id = bu.player_id
),

rolling_stats as (
    select
        *,
        -- Season to date (partition by player_id, season)

        -- Box score stats
        avg(points) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_points_season_to_date,
        avg(field_goals_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_fgm_season_to_date,
        avg(field_goals_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_fga_season_to_date,
        avg(three_pointers_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_3pm_season_to_date,
        avg(three_pointers_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_3pa_season_to_date,
        avg(free_throws_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ftm_season_to_date,
        avg(free_throws_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_fta_season_to_date,
        avg(offensive_rebounds) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_oreb_season_to_date,
        avg(defensive_rebounds) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_dreb_season_to_date,
        avg(rebounds) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_reb_season_to_date,
        avg(assists) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ast_season_to_date,
        avg(steals) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_stl_season_to_date,
        avg(blocks) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_blk_season_to_date,
        avg(turnovers) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_tov_season_to_date,
        avg(personal_fouls) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pf_season_to_date,
        avg(minutes_played) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_mp_season_to_date,
        -- Advanced box score stats
        avg(off_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_off_rating_season_to_date,
        avg(def_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_def_rating_season_to_date,
        avg(net_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_net_rating_season_to_date,
        avg(e_off_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_e_off_rating_season_to_date,
        avg(e_def_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_e_def_rating_season_to_date,
        avg(e_net_rating) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_e_net_rating_season_to_date,
        avg(ast_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ast_pct_season_to_date,
        avg(ast_to) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ast_to_season_to_date,
        avg(ast_ratio) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ast_ratio_season_to_date,
        avg(oreb_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_oreb_pct_season_to_date,
        avg(dreb_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_dreb_pct_season_to_date,
        avg(reb_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_reb_pct_season_to_date,
        avg(tm_tov_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_tm_tov_pct_season_to_date,
        avg(efg_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_efg_pct_season_to_date,
        avg(ts_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_ts_pct_season_to_date,
        avg(usg_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_usg_pct_season_to_date,
        avg(e_usg_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_e_usg_pct_season_to_date,
        avg(e_pace) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_e_pace_season_to_date,
        avg(pace) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pace_season_to_date,
        avg(pace_per40) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pace_per40_season_to_date,
        avg(poss) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_poss_season_to_date,
        avg(pie) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pie_season_to_date,
        -- Usage stats
        avg(pct_fgm) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_fgm_season_to_date,
        avg(pct_fga) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_fga_season_to_date,
        avg(pct_fg3m) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_fg3m_season_to_date,
        avg(pct_fg3a) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_fg3a_season_to_date,
        avg(pct_ftm) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_ftm_season_to_date,
        avg(pct_fta) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_fta_season_to_date,
        avg(pct_oreb) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_oreb_season_to_date,
        avg(pct_dreb) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_dreb_season_to_date,
        avg(pct_reb) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_reb_season_to_date,
        avg(pct_ast) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_ast_season_to_date,
        avg(pct_tov) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_tov_season_to_date,
        avg(pct_stl) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_stl_season_to_date,
        avg(pct_blk) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_blk_season_to_date,
        avg(pct_blka) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_blka_season_to_date,
        avg(pct_pf) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_pf_season_to_date,
        avg(pct_pfd) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_pfd_season_to_date,
        avg(pct_pts) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_pct_pts_season_to_date,
        -- Tracking stats
        avg(speed) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_speed_season_to_date,
        avg(distance) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_distance_season_to_date,
        avg(touches) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_touches_season_to_date,
        avg(secondary_assists) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_secondary_assists_season_to_date,
        avg(free_throw_assists) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_free_throw_assists_season_to_date,
        avg(passes) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_passes_season_to_date,
        avg(contested_field_goals_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_contested_fgm_season_to_date,
        avg(contested_field_goals_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_contested_fga_season_to_date,
        avg(contested_field_goal_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_contested_fg_pct_season_to_date,
        avg(uncontested_field_goals_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_uncontested_fgm_season_to_date,
        avg(uncontested_field_goals_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_uncontested_fga_season_to_date,
        avg(uncontested_field_goal_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_uncontested_fg_pct_season_to_date,
        avg(tracking_field_goal_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_fg_pct_season_to_date,
        avg(defended_field_goals_made) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_defended_fgm_season_to_date,
        avg(defended_field_goals_attempted) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_defended_fga_season_to_date,
        avg(defended_field_goal_pct) over (partition by player_id, season order by game_date rows between unbounded preceding and current row) as avg_defended_fg_pct_season_to_date,

        -- Last game (partition by player_id, season, rows between 1 preceding and current row)

        -- Box score stats
        avg(points) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_points_last_game,
        avg(field_goals_made) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_fgm_last_game,
        avg(field_goals_attempted) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_fga_last_game,
        avg(three_pointers_made) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_3pm_last_game,
        avg(three_pointers_attempted) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_3pa_last_game,
        avg(offensive_rebounds) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_oreb_last_game,
        avg(defensive_rebounds) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_dreb_last_game,
        avg(rebounds) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_reb_last_game,
        avg(assists) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_ast_last_game,
        avg(steals) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_stl_last_game,
        avg(blocks) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_blk_last_game,
        avg(turnovers) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_tov_last_game,
        avg(personal_fouls) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pf_last_game,
        avg(minutes_played) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_mp_last_game,
        -- Advanced box score stats
        avg(off_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_off_rating_last_game,
        avg(def_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_def_rating_last_game,
        avg(net_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_net_rating_last_game,
        avg(e_off_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_e_off_rating_last_game,
        avg(e_def_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_e_def_rating_last_game,
        avg(e_net_rating) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_e_net_rating_last_game,
        avg(ast_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_ast_pct_last_game,
        avg(ast_to) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_ast_to_last_game,
        avg(ast_ratio) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_ast_ratio_last_game,
        avg(oreb_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_oreb_pct_last_game,
        avg(dreb_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_dreb_pct_last_game,
        avg(reb_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_reb_pct_last_game,
        avg(tm_tov_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_tm_tov_pct_last_game,
        avg(efg_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_efg_pct_last_game,
        avg(ts_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_ts_pct_last_game,
        avg(usg_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_usg_pct_last_game,
        avg(e_usg_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_e_usg_pct_last_game,
        avg(e_pace) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_e_pace_last_game,
        avg(pace) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pace_last_game,
        avg(pace_per40) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pace_per40_last_game,
        avg(poss) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_poss_last_game,
        avg(pie) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pie_last_game,
        -- Usage stats
        avg(pct_fgm) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_fgm_last_game,
        avg(pct_fga) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_fga_last_game,
        avg(pct_fg3m) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_fg3m_last_game,
        avg(pct_fg3a) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_fg3a_last_game,
        avg(pct_ftm) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_ftm_last_game,
        avg(pct_fta) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_fta_last_game,
        avg(pct_oreb) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_oreb_last_game,
        avg(pct_dreb) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_dreb_last_game,
        avg(pct_reb) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_reb_last_game,
        avg(pct_ast) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_ast_last_game,
        avg(pct_tov) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_tov_last_game,
        avg(pct_stl) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_stl_last_game,
        avg(pct_blk) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_blk_last_game,
        avg(pct_blka) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_blka_last_game,
        avg(pct_pf) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_pf_last_game,
        avg(pct_pfd) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_pfd_last_game,
        avg(pct_pts) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_pct_pts_last_game,
        -- Tracking stats
        avg(speed) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_speed_last_game,
        avg(distance) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_distance_last_game,
        avg(touches) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_touches_last_game,
        avg(secondary_assists) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_secondary_assists_last_game,
        avg(free_throw_assists) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_free_throw_assists_last_game,
        avg(passes) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_passes_last_game,
        avg(contested_field_goals_made) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_contested_fgm_last_game,
        avg(contested_field_goals_attempted) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_contested_fga_last_game,
        avg(contested_field_goal_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_contested_fg_pct_last_game,
        avg(uncontested_field_goals_made) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_uncontested_fgm_last_game,
        avg(uncontested_field_goals_attempted) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_uncontested_fga_last_game,
        avg(uncontested_field_goal_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_uncontested_fg_pct_last_game,
        avg(tracking_field_goal_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_fg_pct_last_game,
        avg(defended_field_goals_made) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_defended_fgm_last_game,
        avg(defended_field_goals_attempted) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_defended_fga_last_game,
        avg(defended_field_goal_pct) over (partition by player_id, season order by game_date rows between 1 preceding and current row) as avg_defended_fg_pct_last_game,

        -- Last 5 games (partition by player_id, season, rows between 4 preceding and current row)

        -- Box score stats
        avg(points) over (partition by player_id, season order by game_date rows between 4 preceding and current row) as avg_points_last_5,
        avg(field_goals_made) over (partition by player_id, season order by game_date rows between 4 preceding and current row) as avg_fgm_last_5,
        avg(field_goals_attempted) over (partition by player_id, season order by game_date rows between 4 preceding and current row) as avg_fga_last_5,
