        avg(ast_ratio) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_ast_ratio_vs_opp_last_3,
        avg(oreb_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_oreb_pct_vs_opp_last_3,
        avg(dreb_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_dreb_pct_vs_opp_last_3,
        avg(reb_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_reb_pct_vs_opp_last_3,
        avg(tm_tov_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_tm_tov_pct_vs_opp_last_3,
        avg(efg_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_efg_pct_vs_opp_last_3,
        avg(ts_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_ts_vs_opp_last_3,
        avg(usg_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_usg_vs_opp_last_3,
        avg(e_usg_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_e_usg_pct_vs_opp_last_3,
        avg(e_pace) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_e_pace_vs_opp_last_3,
        avg(pace) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pace_vs_opp_last_3,
        avg(pace_per40) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pace_per40_vs_opp_last_3,
        avg(poss) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_poss_vs_opp_last_3,
        avg(pie) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pie_vs_opp_last_3,
        -- Usage stats
        avg(pct_fgm) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_fgm_vs_opp_last_3,
        avg(pct_fga) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_fga_vs_opp_last_3,
        avg(pct_fg3m) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_fg3m_vs_opp_last_3,
        avg(pct_fg3a) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_fg3a_vs_opp_last_3,
        avg(pct_ftm) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_ftm_vs_opp_last_3,
        avg(pct_fta) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_fta_vs_opp_last_3,
        avg(pct_oreb) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_oreb_vs_opp_last_3,
        avg(pct_dreb) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_dreb_vs_opp_last_3,
        avg(pct_reb) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_reb_vs_opp_last_3,
        avg(pct_ast) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_ast_vs_opp_last_3,
        avg(pct_tov) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_tov_vs_opp_last_3,
        avg(pct_stl) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_stl_vs_opp_last_3,
        avg(pct_blk) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_blk_vs_opp_last_3,
        avg(pct_blka) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_blka_vs_opp_last_3,
        avg(pct_pf) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_pf_vs_opp_last_3,
        avg(pct_pfd) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_pfd_vs_opp_last_3,
        avg(pct_pts) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_pct_pts_vs_opp_last_3,
        -- Tracking stats
        avg(speed) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_speed_vs_opp_last_3,
        avg(distance) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_distance_vs_opp_last_3,
        avg(touches) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_touches_vs_opp_last_3,
        avg(secondary_assists) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_secondary_assists_vs_opp_last_3,
        avg(free_throw_assists) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_free_throw_assists_vs_opp_last_3,
        avg(passes) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_passes_vs_opp_last_3,
        avg(contested_field_goals_made) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_contested_fgm_vs_opp_last_3,
        avg(contested_field_goals_attempted) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_contested_fga_vs_opp_last_3,
        avg(contested_field_goal_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_contested_fg_pct_vs_opp_last_3,
        avg(uncontested_field_goals_made) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_uncontested_fgm_vs_opp_last_3,
        avg(uncontested_field_goals_attempted) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_uncontested_fga_vs_opp_last_3,
        avg(uncontested_field_goal_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_uncontested_fg_pct_vs_opp_last_3,
        avg(tracking_field_goal_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_fg_pct_vs_opp_last_3,
        avg(defended_field_goals_made) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_defended_fgm_vs_opp_last_3,
        avg(defended_field_goals_attempted) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_defended_fga_vs_opp_last_3,
        avg(defended_field_goal_pct) over (partition by player_id, season, opponent_team_id order by game_date rows between 2 preceding and current row) as avg_defended_fg_pct_vs_opp_last_3
    from player_stats
    where game_date <= CURRENT_DATE
)

